CREATE OR REPLACE PROCEDURE sp(
    arg1 IN NUMBER,
    arg2 IN VARCHAR2,
    arg3 IN VARCHAR2,
    arg4 IN NUMBER,
    arg5 IN VARCHAR2,
    arg6 IN NUMBER
) IS
    v_threshold NUMBER;
    v_status_text VARCHAR2(32767);
    v_row_count NUMBER;
    v_batch_size NUMBER;
    v_visit_count NUMBER;
    v_dummy NUMBER;

    PROCEDURE run_final_checks(p_archive_case IN BOOLEAN) IS
    BEGIN
        IF v_status_text = 'HIGH_PRIORITY' THEN
            UPDATE "Restaurant_Type"
               SET "ResTypeID" = "ResTypeID" * 2
             WHERE "ResTypeID" > 100;
        ELSIF p_archive_case THEN
            DELETE FROM "Restaurant"
             WHERE "Address" = 'ARCHIVED'
               AND "ResID" < v_threshold - 10;
        ELSIF v_row_count > 15 THEN
            UPDATE "Student"
               SET "LName" = 'BULK_PROCESSED'
             WHERE "StuID" BETWEEN arg4 AND arg4 + 50;
        ELSE
            UPDATE "Restaurant"
               SET "ResName" = arg3
             WHERE "ResID" > v_threshold;
        END IF;
    END run_final_checks;

    PROCEDURE raise_no_data_found IS
    BEGIN
        SELECT 1
          INTO v_dummy
          FROM DUAL
         WHERE 1 = 0;
    END raise_no_data_found;
BEGIN
    v_threshold := ROUND(arg1);
    v_status_text := arg2;
    v_row_count := 0;
    v_batch_size := 10;

    IF v_threshold < 3 THEN
        FOR r IN (
            SELECT "ResID" res_id,
                   "ResName" res_name,
                   "Address" res_address
              FROM "Restaurant"
             WHERE "ResID" < arg1
               AND "ResName" LIKE arg2
        ) LOOP
            v_row_count := v_row_count + 1;

            IF r.res_id > 25 THEN
                UPDATE "Restaurant"
                   SET "ResName" = 'PROMOTED'
                 WHERE "ResID" = r.res_id;
            ELSIF r.res_address = arg3 THEN
                SELECT COUNT(*)
                  INTO v_visit_count
                  FROM "Visits_Restaurant" v
                  JOIN "Student" s
                    ON s."StuID" = v."StuID"
                 WHERE v."ResID" = r.res_id
                   AND s."LName" = arg5;

                IF v_visit_count > 0 THEN
                    UPDATE "Restaurant"
                       SET "Address" = 'RETAINED'
                     WHERE "ResID" = r.res_id;
                ELSE
                    DELETE FROM "Restaurant"
                     WHERE "ResID" = r.res_id
                       AND "ResName" = r.res_name;

                    DELETE FROM "Visits_Restaurant"
                     WHERE "ResID" = r.res_id;

                    DELETE FROM "Type_Of_Restaurant"
                     WHERE "ResID" = r.res_id;
                END IF;
            ELSE
                UPDATE "Restaurant"
                   SET "Address" = 'PENDING'
                 WHERE "ResID" = r.res_id;

                UPDATE "Restaurant"
                   SET "Rating" = arg6
                 WHERE "ResID" = r.res_id;
            END IF;

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

        run_final_checks(FALSE);
    ELSIF v_threshold < 8 THEN
        FOR r IN (
            SELECT "StuID" stu_id,
                   "LName" l_name
              FROM "Student"
             WHERE "StuID" BETWEEN arg4 - 5 AND arg4 + 15
        ) LOOP
            v_row_count := v_row_count + 1;

            IF r.l_name = arg5 THEN
                UPDATE "Student"
                   SET "Major" = 700
                 WHERE "StuID" = r.stu_id
                   AND "LName" = r.l_name;
            END IF;

            IF r.l_name LIKE 'ACTIVE%' THEN
                UPDATE "Student"
                   SET "LName" = 'PROCESSED'
                 WHERE "StuID" = r.stu_id
                   AND "LName" = r.l_name;
            ELSIF r.stu_id > arg4 + 5 THEN
                v_threshold := v_threshold + r.stu_id;
            ELSIF r.l_name = 'EXPIRED' THEN
                DELETE FROM "Student"
                 WHERE "StuID" = r.stu_id
                   AND "LName" = r.l_name;
            END IF;

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

        run_final_checks(FALSE);
    ELSIF v_threshold < 18 THEN
        FOR r IN (
            SELECT "ResTypeID" res_type_id
              FROM "Restaurant_Type"
             WHERE "ResTypeID" > arg6 - 20
        ) LOOP
