            IF r.res_type_id < 50 THEN
                v_status_text := 'LOW_PRIORITY';
            ELSIF r.res_type_id < 150 THEN
                v_status_text := 'MEDIUM_PRIORITY';
            ELSE
                v_status_text := 'HIGH_PRIORITY';
            END IF;

            UPDATE "Restaurant_Type"
               SET "ResTypeID" = r.res_type_id + 10
             WHERE "ResTypeID" = r.res_type_id;

            UPDATE "Type_Of_Restaurant"
               SET "ResTypeID" = "ResTypeID" + 10
             WHERE "ResTypeID" = r.res_type_id;

            IF v_row_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

        run_final_checks(FALSE);
    ELSIF v_threshold < 25 THEN
        UPDATE "Restaurant"
           SET "Address" = 'ARCHIVED'
         WHERE "ResID" < arg1
           AND "ResName" <> arg2;

        run_final_checks(TRUE);
        raise_no_data_found;
    ELSIF v_threshold < 40 THEN
        DELETE FROM "Student"
         WHERE "StuID" < arg4
           AND "LName" = 'OBSOLETE';

        raise_no_data_found;
    ELSE
        UPDATE "Restaurant_Type"
           SET "ResTypeID" = arg6 + 100
         WHERE "ResTypeID" > 200;

        raise_no_data_found;
    END IF;
END sp;
